1	#!/usr/bin/env node
2	import fs from 'node:fs';
3	import { applyPatch, PatchError } from './jsonpatch.mjs';
4	
5	const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
6	const MAX_BYTES = 1048576;
7	const MAX_DEPTH = 1000;
8	
9	class InputError extends Error {
10	  constructor(message, exitCode) {
11	    super(message);
12	    this.exitCode = exitCode;
13	  }
14	}
15	
16	// Reads chunks from a stream until it ends or holds more than MAX_BYTES.
17	async function readCapped(stream) {
18	  const chunks = [];
19	  let total = 0;
20	  try {
21	    for await (const chunk of stream) {
22	      chunks.push(chunk);
23	      total += chunk.length;
24	      if (total > MAX_BYTES) return null;
25	    }
26	  } finally {
27	    stream.destroy();
28	  }
29	  return Buffer.concat(chunks);
30	}
31	
32	function openFile(path) {
33	  try {
34	    return fs.openSync(path, 'r');
35	  } catch (err) {
36	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw new InputError('no such file', 1);
37	    let isDirectory = false;
38	    try {
39	      isDirectory = fs.statSync(path).isDirectory();
40	    } catch {
41	      // Fall through to "cannot read".
42	    }
43	    throw new InputError(isDirectory ? 'is a directory' : 'cannot read', 1);
44	  }
45	}
46	
47	async function readInput(arg) {
48	  const isStdin = arg === '-';
49	  const fd = isStdin ? 0 : openFile(arg);
50	  let bytes;
51	  try {
52	    bytes = await readCapped(fs.createReadStream(null, { fd, autoClose: !isStdin }));
53	  } catch (err) {
54	    throw new InputError(err.code === 'EISDIR' && !isStdin ? 'is a directory' : 'cannot read', 1);
55	  }
56	  if (bytes === null) throw new InputError('too large', 1);
57	  return bytes;
58	}
59	
60	// Depth of valid JSON text, counted without recursion.
61	function jsonDepth(text) {
62	  let depth = 0;
63	  let max = 0;
64	  let inString = false;
65	  for (let i = 0; i < text.length; i++) {
66	    const c = text[i];
67	    if (inString) {
68	      if (c === '\\') i++;
69	      else if (c === '"') inString = false;
70	    } else if (c === '"') {
71	      inString = true;
72	    } else if (c === '[' || c === '{') {
73	      depth++;
74	      if (depth > max) max = depth;
75	    } else if (c === ']' || c === '}') {
76	      depth--;
77	    }
78	  }
79	  return max;
80	}
81	
82	async function loadJson(arg) {
83	  const bytes = await readInput(arg);
84	  let text;
85	  try {
86	    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
87	  } catch {
88	    throw new InputError('invalid UTF-8', 3);
89	  }
90	  let value;
91	  try {
92	    value = JSON.parse(text);
93	  } catch {
94	    throw new InputError('invalid JSON', 3);
95	  }
96	  if (jsonDepth(text) > MAX_DEPTH) throw new InputError('too deep', 3);
97	  return value;
98	}
99	
100	function fail(message, exitCode) {
101	  process.stderr.write(`${message}\n`);
102	  process.exitCode = exitCode;
103	}
104	
105	async function main(args) {
106	  const [patchArg, docArg = '-'] = args;
107	  if (args.length < 1 || args.length > 2 || (patchArg === '-' && docArg === '-')) {
108	    fail(USAGE, 2);
109	    return;
110	  }
111	  const inputs = [];
112	  for (const arg of [patchArg, docArg]) {
113	    try {
114	      inputs.push(await loadJson(arg));
115	    } catch (err) {
116	      if (!(err instanceof InputError)) throw err;
117	      fail(`Error: ${arg === '-' ? 'stdin' : arg}: ${err.message}`, err.exitCode);
118	      return;
119	    }
120	  }
121	  const [patch, doc] = inputs;
122	  let result;
123	  try {
124	    result = applyPatch(doc, patch);
125	  } catch (err) {
126	    if (!(err instanceof PatchError)) throw err;
127	    fail(`Error: ${err.message}`, 4);
128	    return;
129	  }
130	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
131	}
132	
133	await main(process.argv.slice(2));
